-------------------------------------------------------------------------------
-- Workspaces
-------------------------------------------------------------------------------

-- `key` is the XKB keycode of the AZERTY digit row: bindings on keycodes do
-- not depend on the shift level of the symbol (ampersand, eacute, quotedbl,
-- apostrophe, parenleft, egrave, underscore). Tabbed workspaces collect every
-- tiled window into one group.
local workspaces = {
    {name = "Work", key = 10, orientation = "top"},
    {name = "Dev", key = 11, orientation = "top"},
    {name = "www", key = 12, tabbed = true},
    {name = "www-2", key = 13, tabbed = true},
    {name = "Data", key = 14, tabbed = true},
    {name = "Audio", key = 16, orientation = "top"},
    {name = "Other", key = 17, tabbed = true}
}

-- Workspace shown on each monitor right after startup.
local startup_workspaces = {
    {monitor = "eDP-1", workspace = "Work"},
    {monitor = "DP-1", workspace = "Dev"},
    {monitor = "HDMI-A-2", workspace = "www"}
}
local startup_focus = "DP-1"

-- Each workspace is numbered after its position in the list, which is the
-- order of the bar, and carries its name as default name only: selectors use
-- the number.
local id_of = {}
for i, ws in ipairs(workspaces) do
    ws.id = tostring(i)
    id_of[ws.name] = ws.id
end

windows.setup(workspaces)

-- Workspaces are persistent, so that the bar lists the empty ones too. A
-- reload moves every persistent workspace without a monitor to the focused
-- one, so each existing workspace is tied to the monitor it is on whenever
-- the configuration loads; at startup none exists yet, so none is tied. The
-- tie does not keep a workspace from being shown on another monitor.
local current_monitor = {}
for _, w in ipairs(hl.get_workspaces()) do
    if w.id and w.monitor then
        current_monitor[tostring(w.id)] = w.monitor.name
    end
end
for _, ws in ipairs(workspaces) do
    local rule = {workspace = ws.id, default_name = ws.name, persistent = true}
    rule.monitor = current_monitor[ws.id]
    if ws.orientation then rule.layout_opts = {orientation = ws.orientation} end
    hl.workspace_rule(rule)
end

