-- Static rings drawn outside the focus border: a background-coloured gap, then
-- a thin accent line. Applied only once the plugin is loaded (it reloads the
-- configuration on load), since its keys are unknown before that.
local function plugin_loaded(name)
    for _, p in ipairs(hl.get_loaded_plugins()) do
        if p.name == name then return true end
    end
    return false
end

-- Loaded by `hyprpm reload` in scripts/autostart.sh.
if plugin_loaded("scrolloverview") then
    hl.config({
        plugin = {
            scrolloverview = {
                gesture_distance = 300, -- how far is the "max" for the gesture
                scale = 0.5, -- preferred overview scale
                workspace_gap = 50,
                layout = "auto", -- vertical, horizontal, or auto (per-monitor orientation)
                wallpaper = 2, -- 0: global only, 1: per-workspace only, 2: both
                wallpaper_layer = "background", -- auto, background, or bottom
                blur = true, -- blur only the main overview wallpaper
                shadow = {enabled = true, range = 50}
            }
        }
    })
    hl.bind(MOD .. " + g",
            function() hl.plugin.scrolloverview.overview("toggle all") end)
end

if plugin_loaded("borders-plus-plus") then
    hl.config({
        plugin = {
            borders_plus_plus = {
                add_borders = 1,
                natural_rounding = true,
                border_size_1 = 4,
