-- Monitors: left is the next screen, right the previous one; no wrap-around.
-- The pointer moves with the focus, to the centre of the focused window or of
-- an empty monitor: Hyprland refocuses whatever lies under the pointer when a
-- layer such as the launcher closes, and cursor.no_warps leaves it on the old monitor.
local function focus_monitor(direction)
    hl.dispatch(hl.dsp.focus({monitor = direction}))
    local monitor = hl.get_active_monitor()
    if not monitor then return end
    local window = hl.get_active_window()
    local x, y
    if window and window.monitor and window.monitor.name == monitor.name then
        x, y = window.at.x + window.size.x / 2, window.at.y + window.size.y / 2
    else
        x, y = monitor.position.x + monitor.width / 2,
               monitor.position.y + monitor.height / 2
    end
    hl.dispatch(hl.dsp.cursor.move({x = math.floor(x), y = math.floor(y)}))
end
hl.bind(MOD .. " + e", function() focus_monitor("l") end)
hl.bind(MOD .. " + t", function() focus_monitor("r") end)

