-------------------------------------------------------------------------------
-- Startup
-------------------------------------------------------------------------------

-- Every monitor showing an empty workspace outside the list is given one from
-- it: the preferred one when no other monitor shows it, else its startup
-- workspace when no other monitor shows it, else the first unshown one.
-- Startup workspaces are handed out before the fallbacks, so that an unknown
-- monitor never takes one. With `force_startup`, each monitor of
-- `startup_workspaces` is first switched to its startup workspace, whatever
-- it shows. Mirrors and disabled monitors are left alone. At startup, or when
-- a monitor was given a workspace, the focus then goes to `focus_after`, else
-- back to the monitor that had it.
local ASSIGN_DELAY_MS = 300

local named = {}
for _, ws in ipairs(workspaces) do named[ws.name] = true end
local startup_for = {}
for _, entry in ipairs(startup_workspaces) do
    startup_for[entry.monitor] = entry.workspace
end

local function usable(monitor)
    return not monitor.is_mirror and monitor.enabled ~= false
end

local function assign_workspaces(opts)
    local active = hl.get_active_monitor()
    local focus_after = opts.focus_after or (active and active.name)
    local changed = false
    local function show(output, target)
        pcall(hl.dispatch, hl.dsp.focus({monitor = output}))
        pcall(hl.dispatch, hl.dsp
                  .focus({workspace = id_of[target], on_current_monitor = true}))
        changed = true
    end

    if opts.force_startup then
        for _, monitor in ipairs(hl.get_monitors()) do
            local target = startup_for[monitor.name]
            local ws = monitor.active_workspace
            if target and usable(monitor) and not (ws and ws.name == target) then
                show(monitor.name, target)
            end
        end
    end

    local shown, orphans = {}, {}
    for _, monitor in ipairs(hl.get_monitors()) do
        local ws = monitor.active_workspace
        if ws and named[ws.name] then
            shown[ws.name] = true
        elseif usable(monitor) and (not ws or ws.windows == 0) then
            table.insert(orphans, monitor.name)
        end
    end

    local function pick(target)
        if target and not shown[target] then
            shown[target] = true
            return target
        end
    end

    local fallback = {}
    for _, output in ipairs(orphans) do
        local target = pick(opts.preferred) or pick(startup_for[output])
        if target then
            show(output, target)
        else
            table.insert(fallback, output)
        end
    end
    for _, output in ipairs(fallback) do
        for _, ws in ipairs(workspaces) do
            if pick(ws.name) then
                show(output, ws.name)
                break
            end
        end
    end
    if (changed or opts.force_startup) and focus_after then
        pcall(hl.dispatch, hl.dsp.focus({monitor = focus_after}))
    end
end

local function assign_later(opts, delay)
    hl.timer(function() assign_workspaces(opts) end,
             {timeout = delay or ASSIGN_DELAY_MS, type = "oneshot"})
end

-- A monitor plugged in later gets a workspace from Hyprland, possibly one
-- outside the list. The call is deferred so that the monitor has it.
hl.on("monitor.added", function() assign_later({}) end)

-- Moving a workspace to another monitor (the bar's "move workspace to this
-- display") leaves the source monitor on a new empty workspace; it is given
-- the workspace the target monitor showed, as Super+Shift+key swaps them.
-- The event comes before the target monitor switches workspace. Super+Shift+key
-- swaps also emit it, one per workspace, and then find no monitor to fill.
local MOVE_SETTLE_MS = 50
hl.on("workspace.move_to_monitor", function(ws, monitor)
    local previous = monitor and monitor.active_workspace
    local preferred =
        ws and previous and named[previous.name] and previous.name ~= ws.name and
            previous.name or nil
    assign_later(
        {preferred = preferred, focus_after = monitor and monitor.name},
        MOVE_SETTLE_MS)
end)

hl.on("hyprland.start", function()
    assign_later({force_startup = true, focus_after = startup_focus})
    hl.exec_cmd(HYPR_DIR .. "/scripts/autostart.sh")
end)

